public String concatenateErrorCollection(Collection<ApiError> errors) {
        if (errors == null || errors.isEmpty())
            return "";

        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (ApiError error : errors) {
            if (!first)
                sb.append(',');
            sb.append(error.getName());
            first = false;
        }

        return sb.toString();
    }

