PlaceGeometry readGeometry(JsonReader reader) throws IOException {
        double lat = -1.0;
        double lng = -1.0;

        reader.beginObject();
        while (reader.hasNext()) {
            switch (reader.nextName()) {
                case "lat":
                    lat = reader.nextDouble();
                    break;
                case "lng":
                    lng = reader.nextDouble();
                    break;
                default:
                    reader.skipValue();
                    break;
            }
        }
        reader.endObject();
        return new PlaceGeometry(new PlaceLocation(lat, lng));
    }

