@Test
    public void testClear() {
        CharBag bag;

        bag = new CharBag();
        bag.set(0, (char) 1);
        bag.set(1, (char) 1);
        bag.set(63, (char) 1);
        bag.clear();
        assertEquals((Character) (char) 0, (Character) bag.get(0));
        assertEquals((Character) (char) 0, (Character) bag.get(1));
        assertEquals((Character) (char) 0, (Character) bag.get(63));
        assertEquals(64, bag.buffer.length);

        Mask mask = new Mask();
        bag = new CharBag();
        bag.set(0, (char) 1);
        bag.set(1, (char) 1);
        bag.set(63, (char) 1);
        mask.set(63);
        mask.set(0);
        bag.clear(mask);
        assertEquals((Character) (char) 0, (Character) bag.get(0));
        assertNotEquals((Character) (char) 0, (Character) bag.get(1));
        assertEquals((Character) (char) 0, (Character) bag.get(63));
        mask.set(1);
        mask.set(457);
        bag.clear(mask);
        assertEquals((Character) (char) 0, (Character) bag.get(0));
        assertEquals((Character) (char) 0, (Character) bag.get(1));
        assertEquals((Character) (char) 0, (Character) bag.get(63));
        assertEquals(64, bag.buffer.length);
    }

