public short removeLast () {
        if (size == 0) {
            throw new NoSuchElementException("Queue is empty.");
        }

        final short[] values = this.values;
        int tail = this.tail;
        tail--;
        if (tail == -1) {
            tail = values.length - 1;
        }
        final short result = values[tail];
        this.tail = tail;
        size--;

        return result;
    }

