@Test
    public void testDescriptionParser() {
        JosmCoordinatesParser.Result result = JosmCoordinatesParser.parseWithResult("39.095973 -94.573414 Place description");
        double testLatitude = 39.095973;
        double testLongitude = -94.573414;
        assertEquals("Failed to parse 39.095973 -94.573414 Place description", testLatitude, result.coordinates.getLatitude(), 0.000001);
        assertEquals("Failed to parse 39.095973 -94.573414 Place description", testLongitude, result.coordinates.getLongitude(), 0.000001);
        assertEquals("Failed to parse 39.095973 -94.573414 Place description", 20, result.offset);
        result = JosmCoordinatesParser.parseWithResult("39.095973 N, 94.573414 W Place 34 description");
        assertEquals("Failed to parse 39.095973 N, 94.573414 W Place 34 description", testLatitude, result.coordinates.getLatitude(), 0.000001);
        assertEquals("Failed to parse 39.095973 N, 94.573414 W Place 34 description", testLongitude, result.coordinates.getLongitude(), 0.000001);
        assertEquals("Failed to parse 39.095973 N, 94.573414 W Place 34 description", 24, result.offset);
        result = JosmCoordinatesParser.parseWithResult("15N 363936 4328605 Place 34");
        assertEquals("Failed to parse 15N 363936 4328605 Place 34", testLatitude, result.coordinates.getLatitude(), 0.000003);
        assertEquals("Failed to parse 15N 363936 4328605 Place 34", testLongitude, result.coordinates.getLongitude(), 0.000003);
        assertEquals("Failed to parse 15N 363936 4328605 Place 34", 18, result.offset);
        result = JosmCoordinatesParser.parseWithResult("39.095973 N, 94.573414 W");
        assertEquals("Failed to parse 39.095973 N, 94.573414 W", testLatitude, result.coordinates.getLatitude(), 0.000001);
        assertEquals("Failed to parse 39.095973 N, 94.573414 W", testLongitude, result.coordinates.getLongitude(), 0.000001);
        assertEquals("Failed to parse 39.095973 N, 94.573414 W", 24, result.offset);
    }

