public String filterInvalidChars(String s) {
        if (s == null) return null;

        StringBuilder result = new StringBuilder();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (isValidChar(c)) {
                result.append(c);
            }
        }

        return result.toString();
    }

